ITEMS.append({
 "id": "l45-ann-parelasi", "title": "Η παρέλαση της 28ης Οκτωβρίου", "title_en": "The 28 October parade", "type": "announcement", "level": "B2",
 "context_el": "Θα ακούσετε μια ανακοίνωση από τα μεγάφωνα ενός γυμνασίου λίγες μέρες πριν από την εθνική επέτειο.",
 "script": [
  L("Διευθύντρια", "f", "Καλημέρα σε όλους. Όπως ξέρετε, την Τρίτη είναι η εθνική επέτειος της εικοστής ογδόης Οκτωβρίου. Η σχολική γιορτή θα γίνει τη Δευτέρα στις έντεκα, στην αίθουσα εκδηλώσεων. Οι μαθητές της δεύτερης τάξης θα παρουσιάσουν ποιήματα και τραγούδια της εποχής, και όλοι οι γονείς είναι καλεσμένοι.", "Good morning, everyone. As you know, on Tuesday it's the national anniversary of the twenty-eighth of October. The school celebration will take place on Monday at eleven, in the assembly hall. Students from the second year will present poems and songs from that time, and all parents are invited."),
  L("Διευθύντρια", "f", "Την Τρίτη, οι μαθητές που συμμετέχουν στην παρέλαση πρέπει να βρίσκονται στο σχολείο στις εννέα ακριβώς. Τα κορίτσια θα φορούν μπλε φούστα ή παντελόνι και λευκή μπλούζα, και τα αγόρια μπλε παντελόνι και λευκό πουκάμισο. Η σημαία θα κρατηθεί από τη μαθήτρια με τον υψηλότερο βαθμό, την Ευαγγελία Πετρίδου από την τρίτη τάξη.", "On Tuesday, students taking part in the parade must be at school at nine sharp. Girls will wear a blue skirt or trousers and a white blouse, and boys blue trousers and a white shirt. The flag will be carried by the student with the highest marks, Evangelia Petridou from the third year."),
  L("Διευθύντρια", "f", "Η παρέλαση ξεκινά στις έντεκα από την πλατεία του δημαρχείου. Αν βρέχει, η παρέλαση θα ακυρωθεί και θα γίνει μόνο η δοξολογία στη μητρόπολη. Θα σας ενημερώσουμε τη Δευτέρα το απόγευμα με μήνυμα στους γονείς. Σας ευχαριστώ.", "The parade starts at eleven from the town hall square. If it rains, the parade will be cancelled and only the thanksgiving service at the cathedral will take place. We'll let you know on Monday afternoon with a message to parents. Thank you."),
 ],
 "questions": [
  Q("Πότε θα γίνει η σχολική γιορτή;", ["Την Τρίτη στις εννέα", "Τη Δευτέρα στις έντεκα", "Την Κυριακή το απόγευμα", "Την Τρίτη στις έντεκα"], 1, "Η σχολική γιορτή θα γίνει τη Δευτέρα στις έντεκα"),
  Q("Ποια θα κρατήσει τη σημαία;", ["Η μικρότερη μαθήτρια του σχολείου", "Η μαθήτρια με τον υψηλότερο βαθμό", "Η πρόεδρος του μαθητικού συμβουλίου", "Η διευθύντρια"], 1, "Η σημαία θα κρατηθεί από τη μαθήτρια με τον υψηλότερο βαθμό"),
  Q("Τι θα γίνει αν βρέχει;", ["Η παρέλαση θα γίνει την επόμενη μέρα", "Η παρέλαση θα ακυρωθεί και θα γίνει μόνο η δοξολογία", "Η παρέλαση θα γίνει μέσα στο σχολείο", "Οι μαθητές θα φορούν αδιάβροχα"], 1, "Αν βρέχει, η παρέλαση θα ακυρωθεί και θα γίνει μόνο η δοξολογία"),
 ],
 "gloss": {"γυμνασίου": "γυμνάσιο — lower secondary school", "εθνική επέτειο": "εθνική επέτειος — national anniversary", "αίθουσα εκδηλώσεων": "αίθουσα εκδηλώσεων — assembly hall", "καλεσμένοι": "καλεσμένος — invited", "παρέλαση": "παρέλαση — parade", "φούστα": "φούστα — skirt", "σημαία": "σημαία — flag", "βαθμό": "βαθμός — mark, grade", "δημαρχείου": "δημαρχείο — town hall", "δοξολογία": "δοξολογία — thanksgiving service"},
})

ITEMS.append({
 "id": "l45-vm-proponitis", "title": "Μήνυμα από τον προπονητή", "title_en": "A message from the coach", "type": "voicemail", "level": "B2",
 "context_el": "Θα ακούσετε ένα μήνυμα από τον προπονητή της ομάδας μπάσκετ του γιου σας στον τηλεφωνητή σας.",
 "script": [
  L("Προπονητής", "m", "Καλησπέρα, κυρία Βλάχου, ο Θανάσης είμαι, ο προπονητής του Αλέξη. Σας τηλεφωνώ γιατί ο Αλέξης έχει επιλεγεί για τη μικτή ομάδα της περιφέρειας. Είναι μεγάλη επιτυχία, γιατί από όλη την περιοχή επιλέχθηκαν μόνο δώδεκα παιδιά.", "Good evening, Mrs Vlachou, it's Thanasis, Alexis's coach. I'm calling because Alexis has been selected for the regional team. It's a big achievement, because only twelve children were chosen from the whole area."),
  L("Προπονητής", "m", "Οι προπονήσεις της μικτής θα γίνονται κάθε Σάββατο πρωί στη Λάρισα, από τις δέκα έως τις δώδεκα. Ξέρω ότι είναι μια ώρα δρόμος, οπότε σκεφτόμαστε να οργανώσουμε τη μεταφορά μαζί με τους γονείς των άλλων δύο παιδιών από την πόλη μας, να πηγαίνει κάθε φορά ένας.", "Training for the regional team will be every Saturday morning in Larissa, from ten to twelve. I know it's an hour's drive, so we're thinking of organising the transport together with the parents of the other two children from our town, with one going each time."),
  L("Προπονητής", "m", "Χρειάζομαι μέχρι την Πέμπτη την υπογεγραμμένη άδεια γονέα και μια βεβαίωση από τον παιδίατρο ότι μπορεί να αθλείται. Και κάτι ακόμα: ο Αλέξης πρέπει να συνεχίσει να διαβάζει. Αν πέσουν οι βαθμοί του, θα το συζητήσουμε. Πείτε του συγχαρητήρια από μένα!", "I need the signed parental permission form by Thursday, and a certificate from the paediatrician saying he can do sport. And one more thing: Alexis must keep up with his studies. If his marks drop, we'll talk about it. Tell him congratulations from me!"),
 ],
 "questions": [
  Q("Γιατί τηλεφωνεί ο προπονητής;", ["Επειδή ο Αλέξης τραυματίστηκε", "Επειδή ο Αλέξης επιλέχθηκε για τη μικτή ομάδα της περιφέρειας", "Επειδή ακυρώθηκε η προπόνηση", "Επειδή ο Αλέξης δεν πήγε στην προπόνηση"], 1, "ο Αλέξης έχει επιλεγεί για τη μικτή ομάδα της περιφέρειας"),
  Q("Τι προτείνει ο προπονητής για τη μεταφορά στη Λάρισα;", ["Να πηγαίνουν με το λεωφορείο", "Να οργανωθούν οι γονείς των τριών παιδιών και να πηγαίνει κάθε φορά ένας", "Να τους πηγαίνει ο ίδιος", "Να μένουν στη Λάρισα το Σαββατοκύριακο"], 1, "να οργανώσουμε τη μεταφορά μαζί με τους γονείς των άλλων δύο παιδιών ... να πηγαίνει κάθε φορά ένας"),
  Q("Τι χρειάζεται ο προπονητής μέχρι την Πέμπτη;", ["Τη συνδρομή του μήνα", "Την άδεια γονέα και βεβαίωση από τον παιδίατρο", "Μια φωτογραφία του Αλέξη", "Τους βαθμούς του Αλέξη"], 1, "Χρειάζομαι μέχρι την Πέμπτη την υπογεγραμμένη άδεια γονέα και μια βεβαίωση από τον παιδίατρο"),
 ],
 "gloss": {"προπονητή": "προπονητής — coach", "μπάσκετ": "μπάσκετ — basketball", "έχει επιλεγεί": "επιλέγομαι — to be selected", "μικτή": "μικτή (ομάδα) — select team, combined team", "περιφέρειας": "περιφέρεια — region", "προπονήσεις": "προπόνηση — training session", "μεταφορά": "μεταφορά — transport", "υπογεγραμμένη": "υπογεγραμμένος — signed", "παιδίατρο": "παιδίατρος — paediatrician", "αθλείται": "αθλούμαι — to do sport"},
})

ITEMS.append({
 "id": "l45-dia-ora-epistrofis", "title": "Τι ώρα θα γυρίσεις;", "title_en": "What time will you be back?", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε μια μητέρα και τη δεκαεξάχρονη κόρη της να συζητούν για την ώρα που θα γυρίσει σπίτι από ένα πάρτι.",
 "script": [
  L("Κόρη", "f", "Μαμά, το Σάββατο η Ιωάννα έχει πάρτι για τα γενέθλιά της. Μπορώ να γυρίσω στις δύο; Όλοι οι φίλοι μου θα μείνουν μέχρι αργά.", "Mum, on Saturday Ioanna is having a party for her birthday. Can I come back at two? All my friends are staying till late."),
  L("Μητέρα", "f", "Στις δύο; Είσαι δεκαέξι χρονών, Δάφνη. Ξέρεις ότι ο κανόνας είναι μέχρι τις δώδεκα. Και πού είναι αυτό το πάρτι; Θα είναι εκεί οι γονείς της Ιωάννας;", "At two? You're sixteen, Dafni. You know the rule is midnight. And where is this party? Will Ioanna's parents be there?"),
  L("Κόρη", "f", "Ναι, θα είναι στο σπίτι τους, στο Χαλάνδρι, και οι γονείς της θα είναι εκεί όλη την ώρα. Σε παρακαλώ, είναι η καλύτερή μου φίλη. Αν φύγω στις δώδεκα, θα είμαι η μόνη που θα φύγει τόσο νωρίς. Θα ντρέπομαι.", "Yes, it's at their house, in Chalandri, and her parents will be there the whole time. Please, she's my best friend. If I leave at twelve, I'll be the only one leaving so early. I'll be embarrassed."),
  L("Μητέρα", "f", "Εντάξει, ας βρούμε μια μέση λύση. Μπορείς να μείνεις μέχρι τη μία, αλλά θα έρθει να σε πάρει ο μπαμπάς με το αυτοκίνητο, δεν θα γυρίσεις με ταξί. Και θα έχεις το κινητό σου ανοιχτό. Αν δεν σε βρω στο τηλέφωνο, την επόμενη φορά μένεις σπίτι.", "OK, let's find a middle way. You can stay until one, but Dad will come and pick you up in the car; you won't come back by taxi. And you'll keep your phone on. If I can't reach you, next time you stay home."),
 ],
 "questions": [
  Q("Ποιος είναι ο κανόνας για την ώρα επιστροφής της Δάφνης;", ["Μέχρι τις δέκα", "Μέχρι τις δώδεκα", "Μέχρι τη μία", "Δεν υπάρχει κανόνας"], 1, "ο κανόνας είναι μέχρι τις δώδεκα"),
  Q("Γιατί η Δάφνη δεν θέλει να φύγει στις δώδεκα;", ["Επειδή θα πάει μετά σε άλλο πάρτι", "Επειδή θα είναι η μόνη που θα φύγει τόσο νωρίς και θα ντρέπεται", "Επειδή δεν έχει ταξί", "Επειδή θα κοιμηθεί στο σπίτι της φίλης της"], 1, "θα είμαι η μόνη που θα φύγει τόσο νωρίς. Θα ντρέπομαι"),
  Q("Ποια είναι η μέση λύση της μητέρας;", ["Μέχρι τις δύο με ταξί", "Μέχρι τη μία, και θα την πάρει ο μπαμπάς με το αυτοκίνητο", "Μέχρι τις δώδεκα, με τη φίλη της", "Να μην πάει καθόλου"], 1, "Μπορείς να μείνεις μέχρι τη μία, αλλά θα έρθει να σε πάρει ο μπαμπάς"),
 ],
 "gloss": {"δεκαεξάχρονη": "δεκαεξάχρονος — sixteen-year-old", "κανόνας": "κανόνας — rule", "Θα ντρέπομαι": "ντρέπομαι — to be embarrassed", "μέση λύση": "μέση λύση — middle way, compromise", "να σε πάρει": "παίρνω (κάποιον) — to pick (someone) up", "ανοιχτό": "ανοιχτός — on, open", "δεν σε βρω": "βρίσκω (στο τηλέφωνο) — to reach (by phone)", "καλύτερή μου φίλη": "καλύτερη φίλη — best friend", "όλη την ώρα": "όλη την ώρα — the whole time", "μένεις σπίτι": "μένω σπίτι — to stay home"},
})

ITEMS.append({
 "id": "l45-dia-koini-ntanta", "title": "Μια κοινή νταντά", "title_en": "A shared nanny", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε δύο γειτόνισσες που σκέφτονται να μοιραστούν μια νταντά για τα μικρά τους παιδιά.",
 "script": [
  L("Ελένη", "f", "Βάσω, από τον Σεπτέμβριο γυρίζω στη δουλειά, και δεν βρήκα θέση στον δημοτικό παιδικό σταθμό για τη μικρή. Οι ιδιωτικοί είναι πανάκριβοι. Σκέφτηκα κάτι: τι θα έλεγες να πάρουμε μαζί μια νταντά για τα δύο παιδιά;", "Vaso, I'm going back to work in September, and I didn't get a place at the municipal nursery for my little one. The private ones are terribly expensive. I had an idea: what would you say to hiring a nanny together for the two children?"),
  L("Βάσω", "f", "Δεν είναι κακή ιδέα. Τα παιδιά είναι σχεδόν συνομήλικα και παίζουν ήδη μαζί στην παιδική χαρά. Αλλά πού θα μένουν; Δεν θέλω να κουβαλάω τον μικρό κάθε πρωί σε άλλο σπίτι, με το καρότσι, στις επτά.", "It's not a bad idea. The children are almost the same age and already play together at the playground. But where would they stay? I don't want to carry my little boy to another house every morning, with the pushchair, at seven."),
  L("Ελένη", "f", "Μπορούμε να εναλλάσσουμε: μία εβδομάδα στο δικό μου σπίτι, μία στο δικό σου. Έτσι κανείς δεν θα επιβαρύνεται συνέχεια. Και το κόστος θα το μοιράζουμε στη μέση. Η αδελφή μου το κάνει εδώ και έναν χρόνο και είναι πολύ ευχαριστημένη.", "We can alternate: one week at my house, one at yours. That way nobody carries the burden all the time. And we'll split the cost down the middle. My sister has been doing it for a year and is very happy with it."),
  L("Βάσω", "f", "Εντάξει, μ' αρέσει. Το σημαντικότερο όμως είναι να βρούμε τον σωστό άνθρωπο. Θέλω κάποια με εμπειρία και με συστάσεις από άλλες οικογένειες. Ας της κάνουμε μαζί τη συνέντευξη, και ας ζητήσουμε να έρθει μία δοκιμαστική εβδομάδα πριν αποφασίσουμε.", "OK, I like it. But the most important thing is to find the right person. I want someone with experience and references from other families. Let's interview her together, and ask her to come for a trial week before we decide."),
 ],
 "questions": [
  Q("Γιατί η Ελένη χρειάζεται νταντά;", ["Επειδή δεν της αρέσουν οι παιδικοί σταθμοί", "Επειδή γυρίζει στη δουλειά και δεν βρήκε θέση στον δημοτικό παιδικό σταθμό", "Επειδή μετακομίζει", "Επειδή η μικρή είναι άρρωστη"], 1, "γυρίζω στη δουλειά, και δεν βρήκα θέση στον δημοτικό παιδικό σταθμό"),
  Q("Τι προτείνει η Ελένη για το πού θα μένουν τα παιδιά;", ["Πάντα στο σπίτι της Βάσως", "Μία εβδομάδα στο ένα σπίτι και μία στο άλλο", "Στο σπίτι της νταντάς", "Στον παιδικό σταθμό"], 1, "μία εβδομάδα στο δικό μου σπίτι, μία στο δικό σου"),
  Q("Τι ζητάει η Βάσω πριν αποφασίσουν;", ["Μια μικρότερη τιμή", "Συνέντευξη μαζί και μια δοκιμαστική εβδομάδα", "Να μιλήσει με την αδελφή της Ελένης", "Να γνωρίσει την οικογένεια της νταντάς"], 1, "Ας της κάνουμε μαζί τη συνέντευξη, και ας ζητήσουμε να έρθει μία δοκιμαστική εβδομάδα"),
 ],
 "gloss": {"γειτόνισσες": "γειτόνισσα — (female) neighbour", "νταντά": "νταντά — nanny", "παιδικό σταθμό": "παιδικός σταθμός — nursery, day care", "πανάκριβοι": "πανάκριβος — very expensive", "συνομήλικα": "συνομήλικος — of the same age", "καρότσι": "καρότσι — pushchair", "να εναλλάσσουμε": "εναλλάσσω — to alternate", "επιβαρύνεται": "επιβαρύνομαι — to be burdened", "συστάσεις": "σύσταση — reference, recommendation", "δοκιμαστική": "δοκιμαστικός — trial (adj.)"},
})

ITEMS.append({
 "id": "l45-mono-christougenna", "title": "Τα πρώτα μου Χριστούγεννα ως οικοδέσποινα", "title_en": "My first Christmas as a host", "type": "monologue", "level": "B2",
 "context_el": "Θα ακούσετε μια νέα γυναίκα που μιλάει σε ένα podcast για τη χρονιά που έγινε για πρώτη φορά οικοδέσποινα στο χριστουγεννιάτικο τραπέζι της οικογένειας.",
 "script": [
  L("Ζωή", "f", "Κάθε χρόνο τα Χριστούγεννα τα κάναμε στο σπίτι της γιαγιάς μου, στα Τρίκαλα. Πέρσι, όμως, η γιαγιά έσπασε το χέρι της, και κάποιος έπρεπε να αναλάβει. Επειδή είχα μόλις μετακομίσει σε ένα μεγαλύτερο διαμέρισμα, προσφέρθηκα εγώ, χωρίς να καταλαβαίνω τι αναλάμβανα: δεκαπέντε άτομα, τρεις γενιές.", "Every year we spent Christmas at my grandmother's house in Trikala. Last year, though, my grandmother broke her arm, and someone had to take over. Because I had just moved into a bigger flat, I volunteered, without realising what I was taking on: fifteen people, three generations."),
  L("Ζωή", "f", "Η γιαγιά μού υπαγόρευσε από το τηλέφωνο τις συνταγές της: γεμιστή γαλοπούλα, χοιρινό με σέλινο, μελομακάρονα και κουραμπιέδες. Η πρώτη απόπειρα με τα μελομακάρονα ήταν καταστροφή· ήταν σκληρά σαν πέτρες. Τη δεύτερη φορά, η γιαγιά ήρθε και κάθισε δίπλα μου στην κουζίνα και μου έδειχνε με το καλό της χέρι πόσο σιρόπι να ρίχνω.", "My grandmother dictated her recipes to me over the phone: stuffed turkey, pork with celery, melomakarona and kourabiedes. The first attempt at the melomakarona was a disaster; they were as hard as stones. The second time, my grandmother came and sat next to me in the kitchen and showed me with her good hand how much syrup to pour."),
  L("Ζωή", "f", "Την ημέρα των Χριστουγέννων, η γαλοπούλα άργησε μία ώρα, ο θείος μου μάλωσε με τον ξάδερφό μου για πολιτικά, και τα παιδιά έσπασαν μια μπάλα από το δέντρο. Κι όμως, ήταν τα πιο όμορφα Χριστούγεννα που θυμάμαι. Στο τέλος, η γιαγιά σηκώθηκε και είπε: «Από του χρόνου, τα κάνει η Ζωή». Δεν ξέρω αν ήταν έπαινος ή τιμωρία.", "On Christmas Day, the turkey was an hour late, my uncle argued with my cousin about politics, and the children broke a bauble from the tree. And yet it was the most beautiful Christmas I remember. At the end, my grandmother stood up and said: 'From next year, Zoi does it.' I don't know whether it was praise or punishment."),
 ],
 "questions": [
  Q("Γιατί η Ζωή ανέλαβε το χριστουγεννιάτικο τραπέζι;", ["Επειδή η γιαγιά της μετακόμισε", "Επειδή η γιαγιά έσπασε το χέρι της", "Επειδή το ζήτησε η μητέρα της", "Επειδή ήθελε να δείξει το νέο της σπίτι"], 1, "η γιαγιά έσπασε το χέρι της, και κάποιος έπρεπε να αναλάβει"),
  Q("Πώς τη βοήθησε η γιαγιά τη δεύτερη φορά με τα μελομακάρονα;", ["Της έστειλε ένα βίντεο", "Κάθισε δίπλα της στην κουζίνα και της έδειχνε πόσο σιρόπι να ρίχνει", "Τα έφτιαξε μόνη της", "Της έδωσε ένα βιβλίο μαγειρικής"], 1, "η γιαγιά ήρθε και κάθισε δίπλα μου στην κουζίνα και μου έδειχνε ... πόσο σιρόπι να ρίχνω"),
  Q("Τι είπε η γιαγιά στο τέλος της μέρας;", ["Ότι η γαλοπούλα ήταν άψητη", "Ότι από του χρόνου θα τα κάνει η Ζωή", "Ότι δεν θα ξανάρθει", "Ότι τα μελομακάρονα ήταν σκληρά"], 1, "«Από του χρόνου, τα κάνει η Ζωή»"),
 ],
 "gloss": {"οικοδέσποινα": "οικοδέσποινα — hostess", "χριστουγεννιάτικο": "χριστουγεννιάτικος — Christmas (adj.)", "να αναλάβει": "αναλαμβάνω — to take over, take on", "προσφέρθηκα": "προσφέρομαι — to volunteer, offer", "υπαγόρευσε": "υπαγορεύω — to dictate", "γαλοπούλα": "γαλοπούλα — turkey", "σέλινο": "σέλινο — celery", "μελομακάρονα": "μελομακάρονο — honey cookie (Christmas sweet)", "σιρόπι": "σιρόπι — syrup", "έπαινος": "έπαινος — praise"},
})

ITEMS.append({
 "id": "l45-rep-medouses", "title": "Μέδουσες στις παραλίες", "title_en": "Jellyfish on the beaches", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ για την εμφάνιση μεγάλου αριθμού μεδουσών σε παραλίες της Ελλάδας.",
 "script": [
  L("Δημοσιογράφος", "f", "Δεκάδες λουόμενοι χρειάστηκε να ζητήσουν βοήθεια τις τελευταίες μέρες σε παραλίες του Σαρωνικού και του Ευβοϊκού, μετά από τσιμπήματα από μέδουσες. Το είδος που εμφανίζεται συχνότερα φέτος είναι η πελαγία, μια μικρή μωβ μέδουσα με κεντριά που προκαλούν έντονο κάψιμο.", "Dozens of swimmers have had to ask for help in recent days on beaches of the Saronic and Euboean gulfs, after being stung by jellyfish. The species appearing most often this year is pelagia, a small purple jellyfish with stinging cells that cause an intense burning sensation."),
  L("Δημοσιογράφος", "f", "Οι θαλάσσιοι βιολόγοι εξηγούν ότι οι μέδουσες πολλαπλασιάζονται όταν η θερμοκρασία του νερού ανεβαίνει, και ότι η υπεραλίευση έχει μειώσει τα ψάρια και τις χελώνες που τις τρώνε. Οι ισχυροί άνεμοι, επίσης, τις παρασύρουν προς τις ακτές. Γι' αυτό, όπως λένε, το φαινόμενο θα γίνεται όλο και πιο συχνό.", "Marine biologists explain that jellyfish multiply when the water temperature rises, and that overfishing has reduced the fish and turtles that eat them. Strong winds also carry them towards the coast. That's why, they say, the phenomenon will become more and more frequent."),
  L("Δημοσιογράφος", "f", "Τι κάνουμε αν μας τσιμπήσει μέδουσα; Οι γιατροί συμβουλεύουν να ξεπλένουμε την περιοχή με θαλασσινό νερό, ποτέ με γλυκό, και να μην τρίβουμε το δέρμα. Ένα κρύο επίθεμα ανακουφίζει τον πόνο. Αν εμφανιστούν δυσκολία στην αναπνοή ή έντονο πρήξιμο, πρέπει να ζητήσουμε αμέσως ιατρική βοήθεια.", "What do we do if we're stung by a jellyfish? Doctors advise rinsing the area with seawater, never fresh water, and not rubbing the skin. A cold compress relieves the pain. If difficulty breathing or severe swelling appears, we must seek medical help immediately."),
 ],
 "questions": [
  Q("Ποιο είδος μέδουσας εμφανίζεται συχνότερα φέτος;", ["Μια μεγάλη διάφανη μέδουσα", "Η πελαγία, μια μικρή μωβ μέδουσα", "Μια μέδουσα από τον Ατλαντικό", "Μια ακίνδυνη λευκή μέδουσα"], 1, "Το είδος που εμφανίζεται συχνότερα φέτος είναι η πελαγία, μια μικρή μωβ μέδουσα"),
  Q("Ποιος είναι ένας από τους λόγους που πολλαπλασιάζονται οι μέδουσες;", ["Η ρύπανση από τα πλοία", "Η υπεραλίευση, που έχει μειώσει τα ψάρια και τις χελώνες που τις τρώνε", "Τα σκουπίδια στις παραλίες", "Οι πολλοί λουόμενοι"], 1, "η υπεραλίευση έχει μειώσει τα ψάρια και τις χελώνες που τις τρώνε"),
  Q("Με τι πρέπει να ξεπλύνουμε την περιοχή μετά από τσίμπημα;", ["Με γλυκό νερό", "Με θαλασσινό νερό", "Με ξίδι", "Με οινόπνευμα"], 1, "να ξεπλένουμε την περιοχή με θαλασσινό νερό, ποτέ με γλυκό"),
 ],
 "gloss": {"μεδουσών": "μέδουσα — jellyfish", "λουόμενοι": "λουόμενος — swimmer, bather", "τσιμπήματα": "τσίμπημα — sting, bite", "κεντριά": "κεντρί — sting(er)", "κάψιμο": "κάψιμο — burning (sensation)", "πολλαπλασιάζονται": "πολλαπλασιάζομαι — to multiply", "υπεραλίευση": "υπεραλίευση — overfishing", "παρασύρουν": "παρασύρω — to sweep along, carry", "επίθεμα": "επίθεμα — compress", "πρήξιμο": "πρήξιμο — swelling"},
})

ITEMS.append({
 "id": "l45-rep-panelladikes", "title": "Η μέρα των αποτελεσμάτων", "title_en": "Results day", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ την ημέρα που ανακοινώνονται οι βαθμοί των Πανελλαδικών εξετάσεων.",
 "script": [
  L("Δημοσιογράφος", "m", "Από νωρίς το πρωί, χιλιάδες υποψήφιοι σε όλη τη χώρα ανανέωναν συνεχώς τη σελίδα του υπουργείου Παιδείας στα κινητά τους. Σήμερα ανακοινώθηκαν οι βαθμοί των Πανελλαδικών εξετάσεων, από τις οποίες εξαρτάται η εισαγωγή στα πανεπιστήμια.", "Since early morning, thousands of candidates across the country kept refreshing the Ministry of Education page on their phones. Today the marks of the Panhellenic exams were announced, on which admission to university depends."),
  L("Δημοσιογράφος", "m", "Έξω από ένα φροντιστήριο στο Μαρούσι, η δεκαοχτάχρονη Κατερίνα κλαίει από χαρά: με τους βαθμούς της ελπίζει να περάσει στην Ιατρική. «Δύο χρόνια δεν έβγαινα σχεδόν καθόλου», λέει. Δίπλα της, ο φίλος της ο Στέφανος είναι πιο σκεπτικός. «Έγραψα χειρότερα απ' ό,τι περίμενα στα μαθηματικά», μας λέει. «Ίσως ξαναδώσω του χρόνου.»", "Outside a cram school in Marousi, eighteen-year-old Katerina is crying with joy: with her marks she hopes to get into Medicine. 'For two years I hardly went out at all,' she says. Next to her, her friend Stefanos is more thoughtful. 'I did worse than I expected in maths,' he tells us. 'Maybe I'll sit them again next year.'"),
  L("Δημοσιογράφος", "m", "Οι ψυχολόγοι υπενθυμίζουν ότι οι Πανελλαδικές δεν καθορίζουν ολόκληρη τη ζωή ενός νέου. Συμβουλεύουν τους γονείς να στηρίξουν τα παιδιά τους, όποιο κι αν είναι το αποτέλεσμα, και να μην τα συγκρίνουν με άλλους. Το επόμενο βήμα για τους υποψήφιους είναι το μηχανογραφικό δελτίο, όπου δηλώνουν με σειρά προτίμησης τις σχολές που θέλουν.", "Psychologists remind us that the Panhellenic exams don't determine a young person's whole life. They advise parents to support their children whatever the result, and not to compare them with others. The next step for candidates is the application form, where they list the university departments they want in order of preference."),
 ],
 "questions": [
  Q("Από τι εξαρτάται η εισαγωγή στα πανεπιστήμια;", ["Από τη συνέντευξη", "Από τους βαθμούς των Πανελλαδικών εξετάσεων", "Από τους βαθμούς του γυμνασίου", "Από μια κλήρωση"], 1, "οι βαθμοί των Πανελλαδικών εξετάσεων, από τις οποίες εξαρτάται η εισαγωγή στα πανεπιστήμια"),
  Q("Γιατί ο Στέφανος είναι σκεπτικός;", ["Επειδή δεν θέλει να σπουδάσει", "Επειδή έγραψε χειρότερα απ' ό,τι περίμενε στα μαθηματικά", "Επειδή η Κατερίνα πέρασε κι εκείνος όχι", "Επειδή χάλασε το κινητό του"], 1, "Έγραψα χειρότερα απ' ό,τι περίμενα στα μαθηματικά"),
  Q("Τι συμβουλεύουν οι ψυχολόγοι τους γονείς;", ["Να πιέσουν τα παιδιά να ξαναδώσουν", "Να στηρίξουν τα παιδιά τους και να μην τα συγκρίνουν με άλλους", "Να διαλέξουν εκείνοι τις σχολές", "Να τα στείλουν για σπουδές στο εξωτερικό"], 1, "να στηρίξουν τα παιδιά τους, όποιο κι αν είναι το αποτέλεσμα, και να μην τα συγκρίνουν με άλλους"),
 ],
 "gloss": {"Πανελλαδικών εξετάσεων": "Πανελλαδικές εξετάσεις — Panhellenic (university entrance) exams", "υποψήφιοι": "υποψήφιος — candidate", "ανανέωναν": "ανανεώνω — to refresh, renew", "εισαγωγή": "εισαγωγή — admission", "φροντιστήριο": "φροντιστήριο — cram school, tutoring centre", "σκεπτικός": "σκεπτικός — thoughtful, pensive", "ξαναδώσω": "ξαναδίνω (εξετάσεις) — to resit (exams)", "να στηρίξουν": "στηρίζω — to support", "μηχανογραφικό δελτίο": "μηχανογραφικό (δελτίο) — university application form", "σειρά προτίμησης": "σειρά προτίμησης — order of preference"},
})

ITEMS.append({
 "id": "l45-int-kantina", "title": "Μια καντίνα με ιστορία", "title_en": "A food truck with a story", "type": "interview", "level": "B2",
 "context_el": "Θα ακούσετε μια συνέντευξη με έναν νεαρό που έχει μια καντίνα με παραδοσιακό φαγητό στη Θεσσαλονίκη.",
 "script": [
  L("Δημοσιογράφος", "f", "Η καντίνα σας δεν πουλάει τοστ και σουβλάκια, αλλά φαγητά της γιαγιάς. Πώς σας ήρθε αυτή η ιδέα;", "Your food truck doesn't sell toasties and souvlaki, but grandma's food. How did you come up with that idea?"),
  L("Ιδιοκτήτης", "m", "Δούλευα σε ένα γραφείο και κάθε μεσημέρι έτρωγα το ίδιο βαρετό σάντουιτς. Σκεφτόμουν πόσο θα ήθελα ένα πιάτο φασολάκια ή γεμιστά, όπως τα έφτιαχνε η γιαγιά μου στη Δράμα. Όταν η εταιρεία έκλεισε, πήρα την αποζημίωσή μου, αγόρασα ένα παλιό φορτηγάκι και το διαμόρφωσα σε κουζίνα.", "I worked in an office and every lunchtime I ate the same boring sandwich. I thought how much I'd love a plate of green beans or stuffed vegetables, the way my grandmother made them in Drama. When the company closed, I took my severance pay, bought an old van and converted it into a kitchen."),
  L("Δημοσιογράφος", "f", "Ποιες ήταν οι μεγαλύτερες δυσκολίες;", "What were the biggest difficulties?"),
  L("Ιδιοκτήτης", "m", "Οι άδειες, χωρίς αμφιβολία. Χρειάστηκα σχεδόν έναν χρόνο για να πάρω όλα τα χαρτιά από τον δήμο και την υγειονομική υπηρεσία. Και μετά, να πείσω τον κόσμο ότι ένα μαγειρευτό φαγητό από καντίνα μπορεί να είναι καλό. Τώρα έχω πελάτες που έρχονται κάθε μέρα, φοιτητές αλλά και ηλικιωμένους. Κάθε Παρασκευή η γιαγιά μου μαγειρεύει μαζί μου. Λέει ότι είναι η καλύτερη σύνταξη που θα μπορούσε να έχει.", "The permits, without a doubt. I needed almost a year to get all the papers from the municipality and the health authority. And then, to convince people that a home-cooked dish from a food truck can be good. Now I have customers who come every day, students but also elderly people. Every Friday my grandmother cooks with me. She says it's the best retirement she could have."),
 ],
 "questions": [
  Q("Πώς του ήρθε η ιδέα για την καντίνα;", ["Από ένα ταξίδι στο εξωτερικό", "Έτρωγε κάθε μέρα το ίδιο βαρετό σάντουιτς και του έλειπαν τα φαγητά της γιαγιάς", "Του το πρότεινε ένας φίλος", "Είδε μια εκπομπή στην τηλεόραση"], 1, "κάθε μεσημέρι έτρωγα το ίδιο βαρετό σάντουιτς. Σκεφτόμουν πόσο θα ήθελα ένα πιάτο φασολάκια ή γεμιστά"),
  Q("Ποια ήταν η μεγαλύτερη δυσκολία;", ["Το κόστος του φορτηγού", "Οι άδειες από τον δήμο και την υγειονομική υπηρεσία", "Η έλλειψη πελατών τον χειμώνα", "Η εύρεση προσωπικού"], 1, "Οι άδειες, χωρίς αμφιβολία"),
  Q("Τι κάνει η γιαγιά του κάθε Παρασκευή;", ["Πηγαίνει στη Δράμα", "Μαγειρεύει μαζί του στην καντίνα", "Ψωνίζει τα υλικά", "Κάνει τους λογαριασμούς"], 1, "Κάθε Παρασκευή η γιαγιά μου μαγειρεύει μαζί μου"),
 ],
 "gloss": {"καντίνα": "καντίνα — food truck, snack van", "σάντουιτς": "σάντουιτς — sandwich", "φασολάκια": "φασολάκια — green beans", "γεμιστά": "γεμιστά — stuffed vegetables", "αποζημίωσή": "αποζημίωση — severance pay, compensation", "φορτηγάκι": "φορτηγάκι — van", "το διαμόρφωσα": "διαμορφώνω — to convert, shape", "άδειες": "άδεια — permit, licence", "υγειονομική υπηρεσία": "υγειονομική υπηρεσία — health authority", "μαγειρευτό": "μαγειρευτός — home-cooked (stew-type) dish"},
})

ITEMS.append({
 "id": "l45-mono-polydiergasia", "title": "Ο μύθος της πολυδιεργασίας", "title_en": "The myth of multitasking", "type": "monologue", "level": "C1",
 "context_el": "Θα ακούσετε έναν γνωστικό ψυχολόγο που μιλάει σε ένα σεμινάριο για την παραγωγικότητα στην εργασία.",
 "script": [
  L("Ψυχολόγος", "m", "Πολλοί από εμάς είμαστε περήφανοι για την ικανότητά μας να κάνουμε πολλά πράγματα ταυτόχρονα: να απαντάμε σε μηνύματα ενώ παρακολουθούμε μια σύσκεψη, να γράφουμε μια αναφορά με ανοιχτό το ηλεκτρονικό ταχυδρομείο. Οι έρευνες της γνωστικής ψυχολογίας, ωστόσο, δείχνουν ότι αυτό που ονομάζουμε πολυδιεργασία είναι, στις περισσότερες περιπτώσεις, μια ψευδαίσθηση.", "Many of us are proud of our ability to do several things at once: answering messages while following a meeting, writing a report with email open. Research in cognitive psychology, however, shows that what we call multitasking is, in most cases, an illusion."),
  L("Ψυχολόγος", "m", "Όταν πρόκειται για εργασίες που απαιτούν συνειδητή προσοχή, ο εγκέφαλος δεν τις εκτελεί παράλληλα, αλλά εναλλάσσεται γρήγορα από τη μία στην άλλη. Κάθε τέτοια εναλλαγή έχει ένα κόστος: χρειάζεται χρόνος για να «ξαναφορτώσουμε» τους κανόνες και τους στόχους της εργασίας στην οποία επιστρέφουμε. Τα δευτερόλεπτα αυτά αθροίζονται, και τα λάθη πολλαπλασιάζονται.", "When it comes to tasks requiring conscious attention, the brain doesn't carry them out in parallel, but switches rapidly from one to the other. Each such switch has a cost: it takes time to 'reload' the rules and goals of the task we're returning to. Those seconds add up, and errors multiply."),
  L("Ψυχολόγος", "m", "Υπάρχουν, βέβαια, εξαιρέσεις. Μπορούμε να περπατάμε και να μιλάμε ταυτόχρονα, γιατί το περπάτημα έχει γίνει αυτοματοποιημένο. Το πρόβλημα αρχίζει όταν και οι δύο δραστηριότητες απαιτούν τους ίδιους νοητικούς πόρους, όπως η οδήγηση σε άγνωστο δρόμο και μια δύσκολη τηλεφωνική συζήτηση. Γι' αυτό το τηλέφωνο, ακόμα και με ανοιχτή ακρόαση, αυξάνει τον κίνδυνο ατυχήματος.", "There are, of course, exceptions. We can walk and talk at the same time, because walking has become automatic. The problem begins when both activities require the same mental resources, such as driving on an unfamiliar road and a difficult phone conversation. That's why the phone, even on speaker, increases the risk of an accident."),
  L("Ψυχολόγος", "m", "Ένα ακόμα πιο ανησυχητικό εύρημα είναι ότι όσοι πολυδιεργάζονται συστηματικά εκτιμούν συχνά υπερβολικά τις ικανότητές τους. Δεν προτείνω, λοιπόν, να κλείσετε τους υπολογιστές σας. Προτείνω κάτι πιο απλό: να ομαδοποιείτε τις παρόμοιες εργασίες, να ελέγχετε τα μηνύματα σε συγκεκριμένες ώρες και να προστατεύετε κάθε μέρα ένα διάστημα συγκέντρωσης χωρίς διακοπές. Η αφοσίωση σε ένα πράγμα τη φορά δεν είναι πολυτέλεια· είναι μέθοδος.", "An even more worrying finding is that those who habitually multitask often overestimate their abilities. So I'm not suggesting you shut down your computers. I'm suggesting something simpler: group similar tasks, check messages at set times, and protect a period of uninterrupted concentration every day. Devoting yourself to one thing at a time is not a luxury; it's a method."),
 ],
 "questions": [
  Q("Τι δείχνουν, κατά τον ψυχολόγο, οι έρευνες για την πολυδιεργασία;", ["Ότι είναι μια χρήσιμη δεξιότητα", "Ότι στις περισσότερες περιπτώσεις είναι μια ψευδαίσθηση", "Ότι οι νέοι την κάνουν καλύτερα", "Ότι αυξάνει την παραγωγικότητα"], 1, "αυτό που ονομάζουμε πολυδιεργασία είναι, στις περισσότερες περιπτώσεις, μια ψευδαίσθηση"),
  Q("Τι κάνει ο εγκέφαλος με εργασίες που απαιτούν συνειδητή προσοχή;", ["Τις εκτελεί παράλληλα", "Εναλλάσσεται γρήγορα από τη μία στην άλλη, με κόστος σε χρόνο και λάθη", "Αγνοεί τη μία από τις δύο", "Τις κάνει πιο αργά αλλά χωρίς λάθη"], 1, "εναλλάσσεται γρήγορα από τη μία στην άλλη. Κάθε τέτοια εναλλαγή έχει ένα κόστος"),
  Q("Γιατί μπορούμε να περπατάμε και να μιλάμε ταυτόχρονα;", ["Επειδή μιλάμε αργά", "Επειδή το περπάτημα έχει γίνει αυτοματοποιημένο", "Επειδή είναι και τα δύο εύκολα", "Επειδή το κάνουμε από μικροί"], 1, "γιατί το περπάτημα έχει γίνει αυτοματοποιημένο"),
  Q("Τι προτείνει ο ψυχολόγος στο τέλος;", ["Να κλείσουν οι υπολογιστές", "Να ομαδοποιούνται οι εργασίες και να υπάρχει καθημερινά διάστημα συγκέντρωσης χωρίς διακοπές", "Να δουλεύουμε λιγότερες ώρες", "Να μη χρησιμοποιούμε καθόλου email"], 1, "να ομαδοποιείτε τις παρόμοιες εργασίες ... και να προστατεύετε κάθε μέρα ένα διάστημα συγκέντρωσης χωρίς διακοπές"),
 ],
 "gloss": {"γνωστικό": "γνωστικός — cognitive", "πολυδιεργασία": "πολυδιεργασία — multitasking", "ταυτόχρονα": "ταυτόχρονα — at the same time", "αναφορά": "αναφορά — report", "ψευδαίσθηση": "ψευδαίσθηση — illusion", "συνειδητή": "συνειδητός — conscious", "εναλλάσσεται": "εναλλάσσομαι — to switch, alternate", "αθροίζονται": "αθροίζομαι — to add up", "αυτοματοποιημένο": "αυτοματοποιημένος — automatic, automated", "νοητικούς πόρους": "νοητικοί πόροι — mental resources", "ανοιχτή ακρόαση": "ανοιχτή ακρόαση — speakerphone", "εκτιμούν": "εκτιμώ — to estimate, assess", "να ομαδοποιείτε": "ομαδοποιώ — to group", "συγκέντρωσης": "συγκέντρωση — concentration", "αφοσίωση": "αφοσίωση — devotion, dedication"},
})

ITEMS.append({
 "id": "l45-int-antikythera", "title": "Ο μηχανισμός των Αντικυθήρων", "title_en": "The Antikythera mechanism", "type": "interview", "level": "C1",
 "context_el": "Θα ακούσετε μια συνέντευξη με μια ερευνήτρια της ιστορίας της τεχνολογίας για τον μηχανισμό των Αντικυθήρων.",
 "script": [
  L("Δημοσιογράφος", "m", "Πώς βρέθηκε ο μηχανισμός των Αντικυθήρων;", "How was the Antikythera mechanism found?"),
  L("Ερευνήτρια", "f", "Εντελώς τυχαία. Το 1900, σφουγγαράδες από τη Σύμη, που είχαν καταφύγει στα Αντικύθηρα εξαιτίας μιας καταιγίδας, εντόπισαν στον βυθό ένα αρχαίο ναυάγιο του πρώτου αιώνα π.Χ. Από εκεί ανασύρθηκαν χάλκινα και μαρμάρινα αγάλματα, αμφορείς, γυάλινα αγγεία. Ανάμεσά τους υπήρχαν και κάποια διαβρωμένα κομμάτια χαλκού και ξύλου, στα οποία αρχικά κανείς δεν έδωσε σημασία. Μόνο το 1902 ο αρχαιολόγος Βαλέριος Στάης παρατήρησε ότι σε ένα από αυτά διακρινόταν ένας οδοντωτός τροχός.", "Entirely by chance. In 1900, sponge divers from Symi, who had taken shelter at Antikythera because of a storm, spotted an ancient shipwreck from the first century BC on the seabed. From it were brought up bronze and marble statues, amphorae, glass vessels. Among them were some corroded pieces of bronze and wood to which at first nobody paid attention. Only in 1902 did the archaeologist Valerios Stais notice that a gear wheel could be made out in one of them."),
  L("Δημοσιογράφος", "m", "Τι ακριβώς έκανε αυτός ο μηχανισμός;", "What exactly did this mechanism do?"),
  L("Ερευνήτρια", "f", "Ήταν, με απλά λόγια, ένας αναλογικός υπολογιστής για την αστρονομία. Γυρίζοντας μια μανιβέλα, ο χρήστης μπορούσε να δει τη θέση του Ήλιου και της Σελήνης στον ζωδιακό κύκλο, τις φάσεις της Σελήνης και να προβλέψει εκλείψεις. Οι επιγραφές που διαβάστηκαν με σύγχρονες μεθόδους απεικόνισης αναφέρουν και τους πλανήτες, καθώς και τον τετραετή κύκλο των πανελλήνιων αγώνων, όπως οι Ολυμπιακοί. Για να το πετύχει αυτό, ο μηχανισμός είχε δεκάδες χάλκινους οδοντωτούς τροχούς, κομμένους με εντυπωσιακή ακρίβεια.", "It was, in simple terms, an analogue computer for astronomy. By turning a handle, the user could see the position of the Sun and Moon in the zodiac, the phases of the Moon, and predict eclipses. The inscriptions read with modern imaging methods also mention the planets, as well as the four-year cycle of the Panhellenic games, such as the Olympics. To achieve this, the mechanism had dozens of bronze gear wheels, cut with impressive precision."),
  L("Δημοσιογράφος", "m", "Γιατί θεωρείται τόσο μοναδικός;", "Why is it considered so unique?"),
  L("Ερευνήτρια", "f", "Γιατί δεν γνωρίζουμε κανένα άλλο αντικείμενο τέτοιας πολυπλοκότητας από την αρχαιότητα. Μηχανισμοί με ανάλογους οδοντωτούς τροχούς εμφανίζονται ξανά στην Ευρώπη μόνο με τα αστρονομικά ρολόγια του Μεσαίωνα, πάνω από χίλια χρόνια αργότερα. Αυτό δεν σημαίνει ότι ήταν ένα θαύμα χωρίς προηγούμενο. Αρχαίοι συγγραφείς, όπως ο Κικέρων, περιγράφουν παρόμοιες συσκευές. Το πιθανότερο είναι ότι ήταν προϊόν μιας παράδοσης που χάθηκε, και ότι εμείς είχαμε την τύχη να σωθεί ένα μόνο δείγμα της στον βυθό.", "Because we know of no other object of such complexity from antiquity. Mechanisms with similar gear wheels appear again in Europe only with the astronomical clocks of the Middle Ages, more than a thousand years later. That doesn't mean it was a miracle without precedent. Ancient writers, such as Cicero, describe similar devices. Most likely it was the product of a tradition that was lost, and we were lucky that a single example of it survived on the seabed."),
 ],
 "questions": [
  Q("Πώς βρέθηκε το ναυάγιο των Αντικυθήρων;", ["Από μια αρχαιολογική αποστολή", "Τυχαία, από σφουγγαράδες που είχαν καταφύγει εκεί λόγω καταιγίδας", "Από ψαράδες με δίχτυα", "Με δορυφορικές εικόνες"], 1, "σφουγγαράδες από τη Σύμη, που είχαν καταφύγει στα Αντικύθηρα εξαιτίας μιας καταιγίδας, εντόπισαν στον βυθό ένα αρχαίο ναυάγιο"),
  Q("Τι παρατήρησε ο Βαλέριος Στάης το 1902;", ["Ένα χάλκινο άγαλμα", "Έναν οδοντωτό τροχό σε ένα από τα κομμάτια", "Μια επιγραφή για τους Ολυμπιακούς", "Ένα ξύλινο κουτί"], 1, "σε ένα από αυτά διακρινόταν ένας οδοντωτός τροχός"),
  Q("Τι μπορούσε να κάνει ο χρήστης με τον μηχανισμό;", ["Να μετρά τον χρόνο με ακρίβεια λεπτού", "Να βλέπει τη θέση του Ήλιου και της Σελήνης και να προβλέπει εκλείψεις", "Να πλοηγεί το πλοίο", "Να υπολογίζει τους φόρους"], 1, "ο χρήστης μπορούσε να δει τη θέση του Ήλιου και της Σελήνης ... και να προβλέψει εκλείψεις"),
  Q("Τι πιστεύει η ερευνήτρια για την προέλευση του μηχανισμού;", ["Ότι ήταν ένα θαύμα χωρίς προηγούμενο", "Ότι ήταν προϊόν μιας παράδοσης που χάθηκε", "Ότι κατασκευάστηκε τον Μεσαίωνα", "Ότι ήρθε από την Ανατολή"], 1, "Το πιθανότερο είναι ότι ήταν προϊόν μιας παράδοσης που χάθηκε"),
 ],
 "gloss": {"μηχανισμό": "μηχανισμός — mechanism", "σφουγγαράδες": "σφουγγαράς — sponge diver", "είχαν καταφύγει": "καταφεύγω — to take shelter", "ναυάγιο": "ναυάγιο — shipwreck", "ανασύρθηκαν": "ανασύρομαι — to be brought up", "αμφορείς": "αμφορέας — amphora", "διαβρωμένα": "διαβρωμένος — corroded", "οδοντωτός τροχός": "οδοντωτός τροχός — gear wheel", "αναλογικός": "αναλογικός — analogue", "μανιβέλα": "μανιβέλα — crank, handle", "ζωδιακό κύκλο": "ζωδιακός κύκλος — zodiac", "εκλείψεις": "έκλειψη — eclipse", "πολυπλοκότητας": "πολυπλοκότητα — complexity", "Μεσαίωνα": "Μεσαίωνας — Middle Ages", "χωρίς προηγούμενο": "χωρίς προηγούμενο — unprecedented"},
})

rnd = random.Random(45)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
with open(os.path.join(root, "library", "listening", "listening-45.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": ITEMS}, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(ITEMS), "items,", sum(len(i["questions"]) for i in ITEMS), "questions")
